from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(lambda u: u.IncludeWeeklys()
                              .Strikes(-200, 200)
                              .Expiration(0, 730))

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None
        self.last_bar_date = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None
        self.expiry_liquidation_submitted = False

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy.Symbol, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        bar_date = bar.EndTime.date()

        if self.last_bar_date != bar_date:
            self.last_bar_date = bar_date

        end_time = bar.EndTime.time()

        if end_time < time(9, 35) or end_time > time(16, 0):
            return

        self.previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self.previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not (self.fast.IsReady and self.slow.IsReady):
            return

        if self.previous_fast is None or self.previous_slow is None:
            return

        bullish_crossover = (
            self.previous_fast <= self.previous_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        if not bullish_crossover:
            return

        if not (time(9, 45) <= end_time <= time(14, 30)):
            return

        self.TryEnterFromCurrentSlice()

    def TryEnterFromCurrentSlice(self):
        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        chains = self.CurrentSlice.OptionChains
        if chains is None or not chains.ContainsKey(self.option.Symbol):
            self.Debug("Skipped entry: no option chain.")
            return

        chain = chains[self.option.Symbol]
        today = self.Time.date()
        spy_price = self.Securities[self.spy.Symbol].Price

        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() > today
        })

        if not expirations:
            self.Debug("Skipped entry: no valid call expiration.")
            return

        expiration = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiration
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Call entry submitted: " + str(selected.Symbol))

    def OnData(self, slice):
        self.HandleUnexpectedEquityPosition()
        self.HandleExpirationProcessing()

        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        contract = None
        if slice.OptionChains is not None:
            for chain in slice.OptionChains.Values:
                for candidate in chain:
                    if candidate.Symbol == self.held_symbol:
                        contract = candidate
                        break
                if contract is not None:
                    break

        if contract is None:
            self.HandleTimeStop()
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid > 0 and ask > 0:
            midpoint = (bid + ask) / 2.0
            if midpoint >= 1.5 * self.entry_price:
                self.SubmitExit("50% profit target")
                return

        self.HandleTimeStop()

    def HandleTimeStop(self):
        if self.held_symbol is None or self.expiration_date is None:
            return

        if not self.IsImmediatelyPrecedingTradingDay(self.expiration_date):
            return

        if self.Time.time() >= time(15, 45):
            self.SubmitExit("expiration time stop")

    def HandleExpirationProcessing(self):
        if self.held_symbol is None or self.expiration_date is None:
            return

        if self.Time.date() >= self.expiration_date:
            if not self.expiry_liquidation_submitted:
                self.expiry_liquidation_submitted = True
                self.SubmitExit("expiration liquidation")

    def SubmitExit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        self.Transactions.CancelOpenOrders(self.held_symbol)
        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug("Call exit submitted: " + reason)

    def HandleUnexpectedEquityPosition(self):
        holdings = self.Portfolio[self.spy.Symbol]
        if holdings.Quantity != 0:
            self.Liquidate(self.spy.Symbol)
            self.Debug("Unexpected exercise or assignment: SPY position liquidated.")

    def IsImmediatelyPrecedingTradingDay(self, expiration_date):
        candidate = expiration_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return self.Time.date() == candidate

    def OnOrderEvent(self, order_event):
        if order_event.Status != OrderStatus.Filled:
            return

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            self.held_symbol = order_event.Symbol
            self.entry_price = order_event.FillPrice
            self.expiration_date = self.Securities[
                self.held_symbol
            ].Symbol.ID.Date.date()
            self.expiry_liquidation_submitted = False
            self.Debug(
                "Call entry filled: " +
                str(self.held_symbol) +
                " at " +
                str(self.entry_price)
            )

        elif self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            self.Debug("Call exit filled: " + str(self.held_symbol))
            self.held_symbol = None
            self.entry_price = None
            self.expiration_date = None
            self.exit_ticket = None
            self.entry_ticket = None
            self.expiry_liquidation_submitted = False

        if order_event.Symbol.SecurityType == SecurityType.Option:
            if order_event.OrderType == OrderType.OptionExercise:
                self.HandleUnexpectedEquityPosition()

