from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute, Market.USA, True, False, DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute, Market.USA)
        self.option_symbol = option.Symbol
        option.SetFilter(lambda u: u.IncludeWeeklys().Strikes(-100, 100).Expiration(0, 365))

        self.fast = RollingWindow[float](5)
        self.slow = RollingWindow[float](20)

        self.current_interval = None
        self.interval_bars = {}
        self.interval_count = 0
        self.last_signal_bar = None

        self.entry_symbol = None
        self.entry_order_id = None
        self.entry_price = None
        self.exit_order_id = None
        self.expiration = None
        self.no_entry_today = False
        self.last_processed_date = None

    def OnData(self, slice: Slice):
        self.current_slice = slice

        if self.last_processed_date != self.Time.date():
            self.last_processed_date = self.Time.date()
            self.no_entry_today = False

        self.HandleExpirationRisk()
        self.HandleEquityExercise()

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self.UpdateFiveMinuteBar(spy_bar)

        self.EvaluateOpenPosition(slice)

    def UpdateFiveMinuteBar(self, minute_bar: TradeBar):
        local_time = minute_bar.EndTime
        if local_time.tzinfo is not None:
            local_time = local_time.replace(tzinfo=None)

        if local_time.time() < time(9, 30) or local_time.time() > time(16, 0):
            return

        interval_minute = (local_time.minute // 5) * 5
        interval_start = datetime(
            local_time.year, local_time.month, local_time.day,
            local_time.hour, interval_minute
        )

        if self.current_interval != interval_start:
            if self.current_interval is not None and self.interval_count == 5:
                self.EmitFiveMinuteBar()

            self.current_interval = interval_start
            self.interval_bars = {}
            self.interval_count = 0

        minute_key = local_time.replace(second=0, microsecond=0)
        if minute_key not in self.interval_bars:
            self.interval_bars[minute_key] = minute_bar
            self.interval_count += 1

        if local_time.minute % 5 == 4:
            if self.interval_count == 5:
                self.EmitFiveMinuteBar()
            self.current_interval = None
            self.interval_bars = {}
            self.interval_count = 0

    def EmitFiveMinuteBar(self):
        if self.current_interval is None or self.interval_count != 5:
            return

        bars = [self.interval_bars[k] for k in sorted(self.interval_bars)]
        close = bars[-1].Close

        self.fast.Add(float(close))
        self.slow.Add(float(close))

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        end_time = self.current_interval + timedelta(minutes=5)
        if self.last_signal_bar == end_time:
            return
        self.last_signal_bar = end_time

        previous_fast = self.fast[1] if self.fast.Count > 1 else None
        previous_slow = self.slow[1] if self.slow.Count > 1 else None

        if previous_fast is None or previous_slow is None:
            return

        bullish = previous_fast <= previous_slow and self.fast[0] > self.slow[0]
        eligible_time = time(9, 45) <= end_time.time() <= time(14, 30)

        if bullish and eligible_time:
            self.TryEnter()

    def TryEnter(self):
        if self.no_entry_today or self.entry_order_id is not None:
            return

        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            return

        chain = self.current_slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        contracts = [
            c for c in chain
            if c.Right == OptionRight.Call and c.Expiry.date() >= self.Time.date()
        ]

        if not contracts:
            self.Debug("Skipped entry: no call expiration satisfies the rule.")
            return

        expiration = min(c.Expiry.date() for c in contracts)
        same_expiration = [c for c in contracts if c.Expiry.date() == expiration]

        spy_price = self.Securities[self.spy].Price
        eligible = [c for c in same_expiration if c.Strike >= 1.01 * spy_price]

        if not eligible:
            self.Debug("Skipped entry: no call satisfies the strike rule.")
            return

        selected = sorted(
            eligible,
            key=lambda c: (c.Strike, str(c.Symbol))
        )[0]

        self.entry_symbol = selected.Symbol
        self.expiration = expiration
        ticket = self.MarketOrder(self.entry_symbol, 1, tag="Strategy entry")
        self.entry_order_id = ticket.OrderId
        self.Debug(f"Entry submitted: {self.entry_symbol}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = float(order_event.FillPrice)
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.entry_symbol}, price {self.entry_price}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            ):
                self.entry_order_id = None

        if self.exit_order_id == order_event.OrderId:
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_order_id = None

        if order_event.Symbol.SecurityType == SecurityType.Equity:
            if order_event.Symbol == self.spy and (
                getattr(order_event, "IsAssignment", False) or
                getattr(order_event, "IsExercise", False)
            ):
                self.Debug("Unexpected exercise or assignment: liquidating SPY.")
                if self.Portfolio[self.spy].Quantity != 0:
                    self.MarketOrder(
                        self.spy,
                        -self.Portfolio[self.spy].Quantity,
                        tag="Unexpected exercise or assignment"
                    )
                self.no_entry_today = True

    def EvaluateOpenPosition(self, slice: Slice):
        if self.entry_symbol is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.entry_symbol]
        if not holding.Invested or self.exit_order_id is not None:
            return

        security = slice.Bars.get(self.entry_symbol)
        quote = slice.QuoteBars.get(self.entry_symbol)

        if quote is not None:
            bid = float(quote.Bid.Close)
            ask = float(quote.Ask.Close)
            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                if midpoint >= 1.50 * self.entry_price:
                    self.CancelOpenExit()
                    self.exit_order_id = self.MarketOrder(
                        self.entry_symbol,
                        -holding.Quantity,
                        tag="50% profit target"
                    ).OrderId
                    self.Debug("Exit submitted: 50% profit target.")
                    return

        if self.expiration is not None:
            previous_trading_day = self.PreviousTradingDay(self.expiration)
            if (
                self.Time.date() == previous_trading_day and
                self.Time.time() >= time(15, 45)
            ):
                self.exit_order_id = self.MarketOrder(
                    self.entry_symbol,
                    -holding.Quantity,
                    tag="Pre-expiration time stop"
                ).OrderId
                self.Debug("Exit submitted: pre-expiration time stop.")

    def HandleExpirationRisk(self):
        if self.entry_symbol is None or self.expiration is None:
            return

        if self.Time.date() >= self.expiration:
            holding = self.Portfolio[self.entry_symbol]
            if holding.Invested and self.exit_order_id is None:
                self.exit_order_id = self.MarketOrder(
                    self.entry_symbol,
                    -holding.Quantity,
                    tag="Expiration protection"
                ).OrderId
                self.no_entry_today = True
                self.Debug("Exit submitted: expiration protection.")

    def HandleEquityExercise(self):
        if self.Portfolio[self.spy].Quantity != 0:
            if self.entry_symbol is None or self.spy not in self.Portfolio:
                return

    def CancelOpenExit(self):
        if self.exit_order_id is not None:
            self.Transactions.CancelOrder(self.exit_order_id)
            self.exit_order_id = None

    def PreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)
        return candidate.date() if isinstance(candidate, datetime) else candidate.date() if hasattr(candidate, "date") else candidate.date()

