from datetime import datetime, timedelta, time


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False
        )
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = RollingWindow[float](self.slow_period)

        self.bucket_end = None
        self.bucket_bars = []
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_block_date = None
        self.expiration_processing_date = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()
        self._process_option_expiration()

        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            self._evaluate_exit(slice)

        if self.entry_ticket is not None and not self._is_order_open(self.entry_ticket):
            self.entry_ticket = None

        spy_bar = slice.Bars.get(self.spy_symbol)
        if spy_bar is not None:
            self._update_five_minute_bar(spy_bar)

        if self.expiration_block_date == self.Time.date():
            return

        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            return

    def _update_five_minute_bar(self, bar: TradeBar):
        local_end = bar.EndTime.astimezone(self.TimeZone).replace(tzinfo=None)

        if local_end.time() < time(9, 35) or local_end.time() > time(16, 0):
            return

        minute_end = local_end.replace(second=0, microsecond=0)
        minute_of_day = minute_end.hour * 60 + minute_end.minute
        bucket_minute = ((minute_of_day + 4) // 5) * 5
        bucket_end = minute_end.replace(
            hour=bucket_minute // 60,
            minute=bucket_minute % 60
        )

        if self.bucket_end is None:
            self.bucket_end = bucket_end
            self.bucket_bars = [bar]
            return

        if bucket_end != self.bucket_end:
            if len(self.bucket_bars) == 5:
                self._on_completed_five_minute_bar(self.bucket_end)
            self.bucket_end = bucket_end
            self.bucket_bars = [bar]
            return

        if self.bucket_bars:
            previous_end = self.bucket_bars[-1].EndTime.astimezone(
                self.TimeZone
            ).replace(tzinfo=None)
            if minute_end != previous_end + timedelta(minutes=1):
                self.bucket_bars = []
                return

        self.bucket_bars.append(bar)

        if len(self.bucket_bars) == 5:
            self._on_completed_five_minute_bar(bucket_end)

    def _on_completed_five_minute_bar(self, bar_end):
        close = float(self.bucket_bars[-1].Close)
        self.closes.Add(close)

        if not self.closes.IsReady:
            return

        fast_current = sum(
            float(self.closes[i]) for i in range(self.fast_period)
        ) / self.fast_period
        slow_current = sum(
            float(self.closes[i]) for i in range(self.slow_period)
        ) / self.slow_period

        if self.closes.Count < self.slow_period + 1:
            return

        previous_fast = (
            sum(float(self.closes[i]) for i in range(1, self.fast_period + 1))
            / self.fast_period
        )
        previous_slow = (
            sum(float(self.closes[i]) for i in range(1, self.slow_period + 1))
            / self.slow_period
        )

        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)
        bullish_cross = (
            previous_fast <= previous_slow
            and fast_current > slow_current
        )

        if eligible_time and bullish_cross:
            self._try_enter()

    def _try_enter(self):
        if self.entry_ticket is not None and self._is_order_open(self.entry_ticket):
            return

        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            return

        chain = self.CurrentSlice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Skipped selection: no option chain.")
            return

        current_date = self.Time.date()
        candidates_by_expiry = {}

        for contract in chain:
            if contract.Right != OptionRight.Call:
                continue
            expiry = contract.Expiry.date()
            days = (expiry - current_date).days
            if days < 0:
                continue
            candidates_by_expiry.setdefault(expiry, []).append(contract)

        if not candidates_by_expiry:
            self.Debug("Skipped selection: no valid expiration.")
            return

        expiry_date = min(candidates_by_expiry)
        spy_price = float(self.Securities[self.spy_symbol].Price)
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in candidates_by_expiry[expiry_date]
            if float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped selection: no qualifying call strike.")
            return

        candidates.sort(key=lambda c: (float(c.Strike), str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Entry submitted: " + str(selected.Symbol))

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.held_option, self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.entry_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected assignment/exercise handling.")
            self.Liquidate(self.spy_symbol)

    def _evaluate_exit(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self._is_order_open(self.exit_ticket):
            return

        security = self.Securities[self.held_option]
        if not security.Holdings.Invested:
            return

        contract = slice.OptionChains.get(self.option.Symbol)
        quote = None
        if contract is not None:
            for item in contract:
                if item.Symbol == self.held_option:
                    quote = item
                    break

        if quote is not None:
            bid = float(quote.BidPrice)
            ask = float(quote.AskPrice)
            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                if midpoint >= 1.5 * self.entry_price:
                    self.exit_ticket = self.Liquidate(self.held_option)
                    self.Debug("Profit-target exit submitted.")

        expiry_date = self.held_option.ID.Date.date()
        previous_trading_day = self._previous_trading_day(expiry_date)
        local_time = self.Time.astimezone(self.TimeZone).time()

        if (
            self.Time.date() == previous_trading_day
            and local_time >= time(15, 45)
            and self.exit_ticket is None
        ):
            self.exit_ticket = self.Liquidate(self.held_option)
            self.Debug("Expiration time-stop exit submitted.")

    def _process_option_expiration(self):
        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.expiration_block_date = self.Time.date()
            if self.Portfolio[self.held_option].Invested:
                self.Liquidate(self.held_option)
                self.Debug("Expiration liquidation submitted.")

    def _handle_unexpected_spy_position(self):
        if self.Portfolio[self.spy_symbol].Invested:
            self.Debug("Unexpected SPY position; liquidating.")
            self.Liquidate(self.spy_symbol)
            self.expiration_block_date = self.Time.date()

    def _previous_trading_day(self, date_value):
        date_value -= timedelta(days=1)
        while not self.Securities[self.spy_symbol].Exchange.Hours.IsDateOpen(date_value):
            date_value -= timedelta(days=1)
        return date_value

    def _is_order_open(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

