class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 730)
        )

        self.fast_window = deque(maxlen=5)
        self.slow_window = deque(maxlen=20)

        self.active_bucket = None
        self.bucket_values = []
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None
        self.blocked_entry_date = None

    def OnData(self, data: Slice):
        self._handle_unexpected_spy_position()

        current_date = self.Time.date()

        if self.held_symbol is not None and self.expiration_date is not None:
            if current_date >= self.expiration_date:
                self.blocked_entry_date = current_date
                if self._option_quantity() != 0 and not self._exit_is_open():
                    self.Debug(
                        f"{self.Time}: expiration processing; liquidating "
                        f"{self.held_symbol}"
                    )
                    self._submit_exit("expiration")
                return

            if (
                self.Time.weekday() < 5
                and current_date == self.expiration_date - timedelta(days=1)
                and self.Time.time() >= time(15, 45)
                and self._option_quantity() != 0
                and not self._exit_is_open()
            ):
                self.Debug(
                    f"{self.Time}: time-stop exit for {self.held_symbol}"
                )
                self._submit_exit("time stop")
                return

            self._check_profit_target(data)

        if self._spy_bar_is_available(data):
            self._process_spy_minute(data[self.spy])

    def _spy_bar_is_available(self, data):
        return data.ContainsKey(self.spy) and data[self.spy] is not None

    def _process_spy_minute(self, bar):
        local_time = Extensions.ConvertTo(
            bar.EndTime,
            self.TimeZone
        )

        if local_time.date() != self.Time.date():
            return

        if not (time(9, 30) <= local_time.time() <= time(16, 0)):
            return

        bucket_minute = (local_time.minute // 5) * 5
        bucket_start = datetime(
            local_time.year,
            local_time.month,
            local_time.day,
            local_time.hour,
            bucket_minute
        )

        if self.active_bucket is None:
            self.active_bucket = bucket_start

        if bucket_start != self.active_bucket:
            self._finalize_five_minute_bar()
            self.active_bucket = bucket_start
            self.bucket_values = []

        self.bucket_values.append(bar.Close)

    def _finalize_five_minute_bar(self):
        if self.active_bucket is None:
            return

        if len(self.bucket_values) != 5:
            self.bucket_values = []
            return

        close = self.bucket_values[-1]
        self.bucket_values = []

        previous_fast = (
            sum(self.fast_window) / len(self.fast_window)
            if len(self.fast_window) == 5 else None
        )
        previous_slow = (
            sum(self.slow_window) / len(self.slow_window)
            if len(self.slow_window) == 20 else None
        )

        self.fast_window.append(close)
        self.slow_window.append(close)

        if len(self.fast_window) < 5 or len(self.slow_window) < 20:
            return

        current_fast = sum(self.fast_window) / 5
        current_slow = sum(self.slow_window) / 20

        bar_end = self.active_bucket + timedelta(minutes=5)
        end_time = bar_end.time()

        bullish_crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        eligible_time = time(9, 45) <= end_time <= time(14, 30)

        if (
            bullish_crossover
            and eligible_time
            and self.Time.date() != self.blocked_entry_date
            and self.held_symbol is None
            and not self._entry_is_open()
        ):
            self._select_and_enter_option()

    def _select_and_enter_option(self):
        if not self.OptionChainProvider:
            self.Debug(f"{self.Time}: skipped entry; no option chain provider")
            return

        chains = []
        for chain in self.CurrentSlice.OptionChains.Values:
            if chain.Symbol == self.option.Symbol:
                chains.append(chain)

        if not chains:
            self.Debug(f"{self.Time}: skipped entry; no option chain")
            return

        contracts = []
        for chain in chains:
            contracts.extend(list(chain))

        if not contracts:
            self.Debug(f"{self.Time}: skipped entry; empty option chain")
            return

        today = self.Time.date()
        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() > today
        })

        if not expirations:
            self.Debug(f"{self.Time}: skipped entry; no valid expiration")
            return

        expiration = expirations[0]
        spy_price = self.Securities[self.spy].Price
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiration
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: skipped entry; no qualifying call at "
                f"expiration {expiration}"
            )
            return

        candidates.sort(key=lambda contract: (
            contract.Strike,
            str(contract.Symbol)
        ))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        if self.entry_ticket is not None:
            self.Debug(
                f"{self.Time}: submitted entry for {selected.Symbol}"
            )

    def _check_profit_target(self, data):
        if self.held_symbol is None or self._exit_is_open():
            return

        contract = None
        for chain in data.OptionChains.Values:
            for candidate in chain:
                if candidate.Symbol == self.held_symbol:
                    contract = candidate
                    break
            if contract is not None:
                break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self.Debug(
                f"{self.Time}: profit target reached for {self.held_symbol}"
            )
            self._submit_exit("profit target")

    def _submit_exit(self, reason):
        quantity = self._option_quantity()
        if quantity == 0 or self.held_symbol is None:
            return

        if self.exit_ticket is not None:
            self.Transactions.CancelOrder(self.exit_ticket.OrderId)

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

    def OnOrderEvent(self, order_event):
        if order_event.Status != OrderStatus.Filled:
            return

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            self.held_symbol = order_event.Symbol
            self.entry_price = order_event.FillPrice
            self.expiration_date = (
                self.Securities[self.held_symbol].Symbol.ID.Date.date()
            )
            self.Debug(
                f"{self.Time}: entered {self.held_symbol} at "
                f"{self.entry_price}"
            )
            self.entry_ticket = None

        elif (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            self.Debug(
                f"{self.Time}: exited {order_event.Symbol} at "
                f"{order_event.FillPrice}"
            )
            if self._option_quantity() == 0:
                self.held_symbol = None
                self.entry_price = None
                self.expiration_date = None
                self.exit_ticket = None

    def _handle_unexpected_spy_position(self):
        holdings = self.Portfolio[self.spy]
        if holdings.Invested:
            self.Debug(
                f"{self.Time}: unexpected exercise or assignment; "
                f"liquidating SPY equity"
            )
            self.MarketOrder(self.spy, -holdings.Quantity)
            self.blocked_entry_date = self.Time.date()

    def _option_quantity(self):
        if self.held_symbol is None:
            return 0
        return self.Portfolio[self.held_symbol].Quantity

    def _entry_is_open(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    def _exit_is_open(self):
        return (
            self.exit_ticket is not None
            and self.exit_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

