from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute, extendedMarketHours=False)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.bucket_end = None
        self.bucket_bars = {}
        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.no_entry_day = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_processing()

        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            self._evaluate_open_position(slice)

        spy_bar = slice.Bars.get(self.spy.Symbol)
        if spy_bar is None:
            return

        self._process_spy_minute(spy_bar, slice)

    def _process_spy_minute(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime
        if end_time.tzinfo is not None:
            end_time = end_time.replace(tzinfo=None)

        if end_time.time() < time(9, 31) or end_time.time() > time(16, 0):
            return

        minute = end_time.minute
        bucket_minute = ((minute - 1) // 5 + 1) * 5
        bucket_end = end_time.replace(minute=0, second=0, microsecond=0) + timedelta(
            minutes=bucket_minute
        )

        if self.bucket_end is not None and bucket_end != self.bucket_end:
            self._emit_bucket(slice)

        if self.bucket_end != bucket_end:
            self.bucket_end = bucket_end
            self.bucket_bars = {}

        self.bucket_bars[end_time] = bar

        if end_time == bucket_end:
            self._emit_bucket(slice)

    def _emit_bucket(self, slice: Slice):
        if self.bucket_end is None:
            return

        expected = [
            self.bucket_end - timedelta(minutes=i)
            for i in range(5, 0, -1)
        ]

        if any(t not in self.bucket_bars for t in expected):
            self.bucket_end = None
            self.bucket_bars = {}
            return

        bars = [self.bucket_bars[t] for t in expected]
        close = bars[-1].Close

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(self.bucket_end, close)
        self.slow.Update(self.bucket_end, close)

        if (
            previous_fast is not None
            and previous_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
        ):
            bullish = (
                previous_fast <= previous_slow
                and self.fast.Current.Value > self.slow.Current.Value
            )

            if bullish:
                bar_end_time = self.bucket_end.time()
                if time(9, 45) <= bar_end_time <= time(14, 30):
                    self._try_enter(slice)

        self.bucket_end = None
        self.bucket_bars = {}

    def _try_enter(self, slice: Slice):
        if self.entry_ticket is not None and self.entry_ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]:
            return

        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            return

        if self.no_entry_day == self.Time.date():
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug(f"{self.Time}: skipped entry; no option chain")
            return

        current_price = self.Securities[self.spy.Symbol].Price
        if current_price <= 0:
            self.Debug(f"{self.Time}: skipped entry; invalid SPY price")
            return

        target_dte = 30
        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and (contract.Expiry.date() - self.Time.date()).days >= target_dte
        })

        if not eligible_expirations:
            self.Debug(f"{self.Time}: skipped entry; no eligible expiration")
            return

        expiration = min(
            eligible_expirations,
            key=lambda date: ((date - self.Time.date()).days, date)
        )

        minimum_strike = current_price * 1.01
        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiration
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(f"{self.Time}: skipped entry; no qualifying call")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_symbol = selected.Symbol
        self.entry_price = None
        self.exit_ticket = None
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(f"{self.Time}: submitted call entry {selected.Symbol}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"{self.Time}: call entry filled at {self.entry_price}"
                )
            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.entry_ticket = None
                self.entry_symbol = None
                self.entry_price = None

        if order_event.Message:
            message = order_event.Message.lower()
            if "exercise" in message or "assignment" in message:
                self.Debug(
                    f"{self.Time}: unexpected exercise or assignment: "
                    f"{order_event.Message}"
                )
                self.no_entry_day = self.Time.date()

    def _evaluate_open_position(self, slice: Slice):
        if self.entry_price is None or self.entry_symbol is None:
            return

        holding = self.Portfolio[self.entry_symbol]
        if not holding.Invested:
            return

        contract = slice.OptionChains.get(self.option.Symbol)
        quote = None

